def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Test for non-retaliatory opponent at round 11 if all previous are CC
    if n == 10:
        if all(a == 'C' and b == 'C' for a, b in history):
            return 'D'

    # Check test result and switch to exploitation if opponent didn't retaliate
    if n >= 12:
        if len(history) > 11 and history[10][0] == 'D':
            if all(a == 'C' and b == 'C' for a, b in history[:10]):
                if history[11][1] == 'C':
                    return 'D'
                else:
                    # Retaliatory: recover by cooperating for a few rounds
                    if n < 15:
                        return 'C'

    last_opp = history[-1][1]
    if n < 8:
        return 'C' if last_opp == 'C' else 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')

    # Defect on the last round
    if n == 99:
        return 'D'

    if opp_c >= 95:
        return 'C'
    if opp_c <= 3 and n >= 20:
        return 'D'

    recent = history[-12:]
    opp_recent_c = sum(1 for a, b in recent if b == 'C')

    if opp_recent_c == 0:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if opp_recent_c >= 11:
        return 'C'

    perceived_forgiveness = opp_c / n
    if perceived_forgiveness > 0.65:
        if last_opp == 'D' and history[-2][1] == 'C' and rng.random() < 0.7:
            return 'D'
        return 'C'

    if my_c / n > 0.75 and last_opp == 'D':
        return 'D'

    if n > 60 and opp_c > 35 and my_c < 30:
        return 'C'

    if last_opp == 'D':
        if rng.random() < 0.15 + 0.25 * (opp_recent_c / 12):
            return 'C'
        return 'D'

    if n % 10 == 9 and my_c > opp_c + 10:
        return 'D'

    return 'C'
